cat > /tmp/scripts/inventory.py <<'EOF'
import sys, os, re, zlib, binascii
repo = '/app/repo.git'
work = '/tmp/work'
def read_idx(path):
    d = {}
    for line in open(path):
        p = line.split(); d[p[1]] = (int(p[0]), int(p[2].strip('()'),16))
    return d
intact = read_idx(work+'/intact.idx.txt')
damaged = read_idx(work+'/damaged.idx.txt')
# recompute bad entries in damaged pack
data = open(repo+'/objects/pack/pack-0edbe236157d7f40502eaa2e054bc68160f770ab.pack','rb').read()
ents = sorted((v[0], k, v[1]) for k,v in damaged.items())
bad = set()
for i,(off,sha,crc) in enumerate(ents):
    end = ents[i+1][0] if i+1 < len(ents) else len(data)-20
    if (binascii.crc32(data[off:end]) & 0xffffffff) != crc: bad.add(sha)
good_damaged = set(damaged) - bad
open(work+'/bad_pack_entries.txt','w').write('\n'.join(sorted(bad))+'\n')
# loose objects
loose_good, loose_bad = {}, {}
for d in os.listdir(repo+'/objects'):
    if not re.fullmatch('[0-9a-f]{2}', d): continue
    for f in os.listdir(repo+'/objects/'+d):
        sha = d+f
        raw = open(repo+'/objects/'+d+'/'+f,'rb').read()
        try:
            dec = zlib.decompress(raw)
            hdr, _, body = dec.partition(b'\0')
            import hashlib
            ok = hashlib.sha1(dec).hexdigest() == sha
            if ok: loose_good[sha] = hdr.decode()
            else: loose_bad[sha] = 'sha-mismatch:'+hdr.decode(errors='replace')
        except Exception as e:
            loose_bad[sha] = 'inflate-error:%s len=%d first=%s zeros=%d' % (e, len(raw), raw[:8].hex(), raw.count(0))
print("loose good:", len(loose_good), " loose bad:", len(loose_bad))
for s,v in sorted(loose_bad.items()): print("  BAD LOOSE", s, v)
available = set(intact) | good_damaged | set(loose_good)
print("\n=== 37 bad pack entries: where else available ===")
for s in sorted(bad):
    src = []
    if s in intact: src.append('intact-pack')
    if s in loose_good: src.append('loose-good')
    if s in loose_bad: src.append('loose-BAD')
    print(" ", s, ','.join(src) if src else 'NOWHERE')
print("\n=== 6 bad loose objects: where else available ===")
for s in sorted(loose_bad):
    src = []
    if s in intact: src.append('intact-pack')
    if s in good_damaged: src.append('damaged-pack-good')
    if s in bad: src.append('damaged-pack-BAD')
    print(" ", s, ','.join(src) if src else 'NOWHERE')
print("\n=== loose good objects: overlap ===")
print("  loose good also in intact pack:", len(set(loose_good)&set(intact)), " also in damaged pack:", len(set(loose_good)&set(damaged)), " loose-only:", len(set(loose_good)-set(intact)-set(damaged)))
# refs & reflogs
shas = {}
def add(sha, where):
    if re.fullmatch('[0-9a-f]{40}', sha) and sha != '0'*40: shas.setdefault(sha, set()).add(where)
for root,_,files in os.walk(repo+'/logs'):
    for f in files:
        p = os.path.join(root,f)
        for line in open(p):
            parts = line.split()
            add(parts[0], 'log:'+p[len(repo)+1:]); add(parts[1], 'log:'+p[len(repo)+1:])
for root,_,files in os.walk(repo+'/refs'):
    for f in files:
        p = os.path.join(root,f); add(open(p).read().strip(), 'ref:'+p[len(repo)+1:])
for line in open(repo+'/packed-refs'):
    if line.startswith('#'): continue
    line=line.strip().lstrip('^'); add(line.split()[0], 'packed-refs')
print("\n=== referenced SHAs (refs+reflogs):", len(shas))
missing = []
for s in sorted(shas):
    if s not in available: missing.append(s)
print("  available:", len(shas)-len(missing), " MISSING:", len(missing))
for s in missing:
    src=[]
    if s in bad: src.append('damaged-pack-BAD')
    if s in loose_bad: src.append('loose-BAD')
    print("  MISSING", s, ','.join(src) if src else 'no-trace', sorted(shas[s])[:3])
open(work+'/available.txt','w').write('\n'.join(sorted(available))+'\n')
print("\nTotal distinct available objects:", len(available))
EOF
