cd /tmp/work && S=recover.git && awk '$2=="tree"{print $1}' allobjs.txt | while read t; do git --git-dir=$S ls-tree $t | sed "s/^/$t /"; done > trees.txt && wc -l trees.txt && cat > /tmp/scripts/dag.py <<'EOF'
import re, os, collections
work='/tmp/work'
commits={}
for line in open(work+'/commits.txt'):
    m = re.match(r'(\w+) tree=(\w+) parents=(\S*) author=\[(.*?)\] subj=\[(.*)\]$', line.rstrip('\n'))
    sha, tree, parents, author, subj = m.groups()
    commits[sha] = dict(tree=tree, parents=[p for p in parents.split(',') if p], author=author, subj=subj)
children = collections.defaultdict(list)
for s,c in commits.items():
    for p in c['parents']: children[p].append(s)
missing_parents = {p for c in commits.values() for p in c['parents'] if p not in commits}
print("known commits:", len(commits), " missing parents referenced:", sorted(missing_parents))
# tips referenced by refs/reflogs
reflog_shas=set()
repo='/app/repo.git'
for root,_,files in os.walk(repo+'/logs'):
    for f in files:
        for line in open(os.path.join(root,f)):
            a,b = line.split()[:2]; reflog_shas.add(a); reflog_shas.add(b)
reflog_shas.discard('0'*40)
heads = [s for s in commits if not children[s]]
print("commits with no children (heads):")
for h in heads:
    c=commits[h]; print("  ", h[:10], c['author'].split('<')[0].strip(), '|', c['subj'], '| in-reflog' if h in reflog_shas else '| NOT in reflog')
def ancestors(s):
    seen=set(); stack=[s]
    while stack:
        x=stack.pop()
        if x in seen: continue
        seen.add(x)
        if x in commits: stack.extend(commits[x]['parents'])
    return seen
tips = {'main':'904cdd39e94b7267b40adfc4caeeed4ffb91e06c','develop(reflog tip)':'bfa5ad83b686bad7e2e4e0f8b570bb3a2315e5bf','hotfix/1.2.1':'69305d3a6d68e96388e91dcdde3447ea7042944f','mirror/feature/cache-warmup':'aef3e022037917637248671a8d936d6710f61da6','mirror/feature/retry-policy':'d13c784d66243541536833780676efba0d86042a','old cache-warmup':'43b85f3057459e6407714c6488448e713c1ef340','old retry-policy':'e4a74c45e1bd251a2b145946e3a0ce2c8c7664eb'}
for name,t in tips.items():
    anc = ancestors(t)
    miss = sorted(a for a in anc if a not in commits)
    print("tip %-30s %s ancestors=%d missing=%s" % (name, t[:10], len(anc), [m[:10] for m in miss]))
# commits reachable from any reflog sha
allanc=set()
for s in reflog_shas:
    allanc |= ancestors(s)
print("reachable from refs/reflogs: %d commits, %d missing" % (len([a for a in allanc if a in commits]), len([a for a in allanc if a not in commits])))
print("known commits NOT reachable from reflogs:", [s[:10] for s in commits if s not in allanc])
# print the chain around 8356afa2
def chain_up(s, n=12):
    out=[]
    while s and n>0:
        if s in commits:
            c=commits[s]; out.append("%s %s | %s" % (s[:10], c['author'].split('<')[0].strip(), c['subj'])); s = c['parents'][0] if c['parents'] else None
        else:
            out.append("%s MISSING" % s[:10]); break
        n-=1
    return out
print("\nchain down from 8356afa2 children:")
def chain_down(s, n=15):
    out=[]
    while s and n>0:
        c=commits[s]; out.append("%s %s | %s | children=%s" % (s[:10], c['author'].split('<')[0].strip(), c['subj'], [x[:10] for x in children[s]])); 
        s = children[s][0] if children[s] else None; n-=1
    return out
for l in chain_down('8356afa2f4b5ed54b0bc389a59434daaf6d09909'): print("  ", l)
# trees referencing missing objects
missing_objs = set(open(work+'/bad_pack_entries.txt').read().split())
avail = set(l.split()[0] for l in open(work+'/allobjs.txt'))
missing_objs -= avail
missing_objs |= {'1581703b7fa63a8c459216ddfdbf7d553642e813','3695dba707dabc7cfc5d3fd31d5b51210f320873','484b4b97230a00acb0873bb582d80fe9b780e271','576f4f21182ceb3e810001b16056524ab67423fe','a0b8dca738bf9020a3e88252f9f53ab493c1469f','a541433306a2cfb95214da3e1cd71ed2fdbbb6a7'}
print("\nreferences to missing objects from known trees/commits:")
treerefs = collections.defaultdict(list)
for line in open(work+'/trees.txt'):
    t, mode, typ, rest = line.rstrip('\n').split(None,3)
    sha, name = rest.split('\t')
    if sha in missing_objs: treerefs[sha].append((t[:10], mode, name))
for s,c in commits.items():
    if c['tree'] in missing_objs: treerefs[c['tree']].append((s[:10],'commit-tree',c['subj']))
    for p in c['parents']:
        if p in missing_objs: treerefs[p].append((s[:10],'commit-parent',c['subj']))
for m in sorted(missing_objs):
    print("  %s <- %s" % (m[:10], treerefs.get(m, 'UNREFERENCED')))
